begin
wwv_flow_imp_page.create_page(
 p_id=>16
,p_name=>'Available Stock'
,p_alias=>'AVAILABLE-STOCK'
,p_step_title=>'Available Stock'
,p_autocomplete_on_off=>'OFF'
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'18'
,p_created_on=>wwv_flow_imp.dz('20260930053346Z')
,p_last_updated_on=>wwv_flow_imp.dz('20260930185925Z')
,p_created_by=>'MDASIFAHMED113344@GMAIL.COM'
,p_last_updated_by=>'MDASIFAHMED113344@GMAIL.COM'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(42729464925046699451)
,p_plug_name=>'Available Stock'
,p_static_id=>'available-stock'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    p.PRODUCT_ID,',
'    p.PRODUCT_NAME,',
'    p.CATEGORY,',
'    p.PRICE,',
'    GREATEST(NVL(SUM(CASE WHEN s.TRANSACTION_TYPE = ''IN'' THEN s.QUANTITY ',
'                           WHEN s.TRANSACTION_TYPE = ''OUT'' THEN -s.QUANTITY ',
'                           ELSE 0 END), 0), 0) AS AVAILABLE_STOCK',
'FROM TBL_PRODUCTS p',
'LEFT JOIN TBL_STOCK_INVENTORY s ON p.PRODUCT_ID = s.PRODUCT_ID',
'GROUP BY p.PRODUCT_ID, p.PRODUCT_NAME, p.CATEGORY, p.PRICE;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
